import {
  JsonTreeView as JsonTreeViewPrimitive,
  useJsonTreeView,
  type JsonTreeViewRootProps,
  type JsonTreeViewRootProviderProps,
  type JsonTreeViewTreeProps,
  type UseJsonTreeViewProps,
  type UseJsonTreeViewReturn,
} from '@ark-ui/solid/json-tree-view';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import { ChevronRightIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './JsonTreeView.module.css';

function JsonTreeView(props: JsonTreeViewRootProps) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <JsonTreeViewPrimitive.Root
      asChild={local.asChild}
      {...others}
      data-slot="json-tree-view-root"
      class={clsx(styles.root, local.class)}
    >
      {local.children}
    </JsonTreeViewPrimitive.Root>
  );
}

function JsonTreeViewRootProvider(props: JsonTreeViewRootProviderProps) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <JsonTreeViewPrimitive.RootProvider
      asChild={local.asChild}
      {...others}
      data-slot="json-tree-view-root-provider"
      class={clsx(styles.root, local.class)}
    >
      {local.children}
    </JsonTreeViewPrimitive.RootProvider>
  );
}

function JsonTreeViewTree(props: JsonTreeViewTreeProps) {
  const [local, others] = splitProps(props, ['arrow', 'class']);

  return (
    <JsonTreeViewPrimitive.Tree
      {...others}
      arrow={local.arrow ?? <ChevronRightIcon aria-hidden="true" />}
      data-slot="json-tree-view-tree"
      class={clsx(styles.tree, local.class)}
    />
  );
}

export { JsonTreeView, JsonTreeViewRootProvider, JsonTreeViewTree, useJsonTreeView };
export type {
  JsonTreeViewRootProps,
  JsonTreeViewRootProviderProps,
  JsonTreeViewTreeProps,
  UseJsonTreeViewProps,
  UseJsonTreeViewReturn,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    color: var(--moduix-color-foreground);
    font-family: var(--moduix-font-mono);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .tree,
  .root :where([data-scope='json-tree-view'][data-part='branch']) {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
  }

  .root
    :where(
      [data-scope='json-tree-view'][data-part='branch-control'],
      [data-scope='json-tree-view'][data-part='item']
    ) {
    position: relative;
    z-index: 0;
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    min-height: calc(var(--moduix-line-height-text-xs) + (var(--moduix-spacing-0-5) * 2));
    align-items: center;
    gap: var(--moduix-spacing-0-5);
    border: 0;
    border-radius: var(--moduix-radius-xs);
    padding-block: var(--moduix-spacing-0-5);
    padding-inline-end: var(--moduix-spacing-1);
    padding-inline-start: calc(
      var(--moduix-spacing-1) + var(--moduix-spacing-1) + ((var(--depth, 1) - 1) * 1rem)
    );
    background-color: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
    outline: none;
    text-align: start;
    transition:
      color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);
    user-select: none;

    &::before {
      position: absolute;
      z-index: -1;
      inset-block: 0;
      inset-inline-end: 0;
      inset-inline-start: calc(var(--moduix-spacing-1) + ((var(--depth, 1) - 1) * 1rem));
      border-radius: inherit;
      background-color: transparent;
      box-shadow: inset 0 0 0 var(--moduix-border-width-sm) transparent;
      content: '';
      pointer-events: none;
      transition:
        background-color var(--moduix-transition-default),
        box-shadow var(--moduix-transition-default);
    }

    @media (hover: hover) {
      &:not([data-disabled]):hover {
        &::before {
          background-color: color-mix(
            in oklab,
            var(--moduix-color-accent) 72%,
            var(--moduix-color-background)
          );
        }
      }
    }

    &[data-selected] {
      &::before {
        background-color: color-mix(
          in oklab,
          var(--moduix-color-accent) 72%,
          var(--moduix-color-background)
        );
      }
    }

    &:focus-visible,
    &[data-focus] {
      &::before {
        box-shadow: inset 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-ring);
      }
    }

    &[data-disabled] {
      color: var(--moduix-color-muted-foreground);
      cursor: default;
    }
  }

  .root :where([data-scope='json-tree-view'][data-part='branch-indicator']) {
    display: inline-flex;
    width: var(--moduix-spacing-3);
    height: var(--moduix-spacing-3);
    flex: 0 0 var(--moduix-spacing-3);
    align-items: center;
    justify-content: center;
    color: color-mix(
      in oklab,
      var(--moduix-color-muted-foreground) 42%,
      var(--moduix-color-foreground)
    );
    transition: transform var(--moduix-transition-default);

    &[data-state='open'] {
      transform: rotate(90deg);
    }

    & svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }
  }

  .root
    :where(
      [data-scope='json-tree-view'][data-part='branch-text'],
      [data-scope='json-tree-view'][data-part='item-text']
    ) {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .root :where([data-scope='json-tree-view'][data-part='branch-content']) {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
    overflow: hidden;
  }

  .root :where([data-kind='key']) {
    color: color-mix(in oklab, var(--moduix-color-chart-1) 72%, var(--moduix-color-foreground));
    font-weight: var(--moduix-weight-medium);
  }

  .root :where([data-kind='colon'], [data-kind='brace'], [data-kind='preview-text']) {
    color: var(--moduix-color-muted-foreground);
  }

  .root :where([data-kind='brace']) {
    font-weight: var(--moduix-weight-medium);
  }

  .root :where([data-kind='preview'][data-type='string']) {
    color: color-mix(in oklab, var(--moduix-color-success) 78%, var(--moduix-color-foreground));
  }

  .root
    :where([data-kind='preview'][data-type='number'], [data-kind='preview'][data-type='bigint']) {
    color: color-mix(in oklab, var(--moduix-color-chart-3) 78%, var(--moduix-color-foreground));
  }

  .root :where([data-kind='preview'][data-type='boolean']) {
    color: color-mix(in oklab, var(--moduix-color-chart-4) 74%, var(--moduix-color-foreground));
    font-weight: var(--moduix-weight-medium);
  }

  .root
    :where([data-kind='preview'][data-type='null'], [data-kind='preview'][data-type='undefined']) {
    color: var(--moduix-color-muted-foreground);
    font-style: italic;
    font-weight: var(--moduix-weight-medium);
  }

  .root
    :where(
      [data-kind='preview'][data-type='error'],
      [data-kind='error-stack'],
      [data-kind='operator']
    ) {
    color: var(--moduix-color-destructive);
  }

  .root
    :where(
      [data-kind='preview'][data-type='function'],
      [data-kind='function-type'],
      [data-kind='function-body']
    ) {
    color: color-mix(in oklab, var(--moduix-color-chart-5) 72%, var(--moduix-color-foreground));
    font-style: italic;
  }

  .root :where([data-kind='constructor']) {
    color: var(--moduix-color-muted-foreground);
    font-weight: var(--moduix-weight-medium);
  }
}
